<?php declare(strict_types=1); $title = 'Registrar compra'; $rows = $values['items'] ?: [['producto_id'=>'','codigo_lote'=>'','fecha_vencimiento'=>'','cantidad'=>'','costo_unitario'=>'']]; ?>
<section class="mx-auto max-w-5xl"><div class="mb-6"><a href="<?= e($baseUrl) ?>/compras" class="text-sm font-semibold text-emerald-800">← Compras</a><h1 class="mt-3 text-3xl font-bold text-slate-900">Registrar compra</h1><p class="mt-2 text-sm text-slate-600">Cada línea crea un lote y suma la cantidad recibida al inventario.</p></div>
<?php if ($errors): ?><div role="alert" class="mb-5 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><ul><?php foreach ($errors as $message): ?><li><?= e($message) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if (!$providers || !$products): ?><div class="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">Para registrar compras necesitas al menos un proveedor y un producto activos.</div><?php else: ?>
<form method="post" action="<?= e($baseUrl) ?>/compras/crear" class="space-y-6"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>">
<div class="grid gap-4 rounded-xl border border-slate-200 bg-white p-5 sm:grid-cols-2"><label class="text-sm font-semibold">Proveedor<select required name="proveedor_id" class="mt-1 block min-h-11 w-full rounded-lg border border-slate-300 px-3 font-normal"><option value="">Selecciona proveedor</option><?php foreach ($providers as $provider): ?><option value="<?= e($provider['id']) ?>" <?= (string)$values['proveedor_id']===(string)$provider['id']?'selected':'' ?>><?= e($provider['nombre']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-semibold">N.º de documento (opcional)<input name="numero_documento" maxlength="80" value="<?= e($values['numero_documento']) ?>" class="mt-1 block min-h-11 w-full rounded-lg border border-slate-300 px-3 font-normal"></label><label class="text-sm font-semibold sm:col-span-2">Observaciones<textarea name="observaciones" maxlength="500" rows="2" class="mt-1 block w-full rounded-lg border border-slate-300 p-3 font-normal"><?= e($values['observaciones']) ?></textarea></label></div>
<div class="rounded-xl border border-slate-200 bg-white p-5"><div class="mb-4 flex items-center justify-between"><h2 class="text-lg font-bold">Productos y lotes</h2><button type="button" id="add-row" class="rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold">Añadir línea</button></div><div id="purchase-lines" class="space-y-4">
<?php foreach ($rows as $i => $item): ?><?php $selectedProductLabel = ''; $selectedProductStock = null; foreach ($products as $candidate) { if ((string)$candidate['id'] === (string)$item['producto_id']) { $selectedProductLabel = $candidate['codigo'].' · '.$candidate['nombre'].' ('.$candidate['unidad_medida'].')'; $selectedProductStock = $candidate['stock_actual']; break; } } ?><div class="purchase-line grid gap-3 rounded-lg border border-slate-200 p-4 sm:grid-cols-2 lg:grid-cols-3"><div><span class="text-sm font-semibold">Producto</span><input type="hidden" name="items[<?= $i ?>][producto_id]" value="<?= e($item['producto_id']) ?>" class="product-id"><button type="button" class="open-product-modal mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 text-left text-sm font-normal"><?= e($selectedProductLabel ?: 'Seleccionar producto…') ?></button><span class="product-stock text-xs text-slate-500"><?= $selectedProductStock !== null ? 'Stock actual: '.e(number_format((float)$selectedProductStock, 3)).' unidades' : '' ?></span></div><label class="text-sm font-semibold">Código de lote<input required name="items[<?= $i ?>][codigo_lote]" maxlength="100" value="<?= e($item['codigo_lote']) ?>" class="mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 font-normal"></label><label class="text-sm font-semibold">Vencimiento<input type="date" name="items[<?= $i ?>][fecha_vencimiento]" value="<?= e($item['fecha_vencimiento']) ?>" class="mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 font-normal"></label><label class="text-sm font-semibold">Cantidad<input required type="number" min="0.001" step="0.001" name="items[<?= $i ?>][cantidad]" value="<?= e($item['cantidad']) ?>" class="mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 font-normal"></label><label class="text-sm font-semibold">Costo unitario (S/)<input required type="number" min="0" step="0.0001" name="items[<?= $i ?>][costo_unitario]" value="<?= e($item['costo_unitario']) ?>" class="mt-1 block min-h-10 w-full rounded border border-slate-300 px-2 font-normal"></label><div class="flex items-end"><button type="button" class="remove-row rounded px-3 py-2 text-sm font-semibold text-red-700">Quitar línea</button></div></div><?php endforeach; ?>
 </div><p class="mt-4 text-xs text-slate-500">El costo total se calcula automáticamente al guardar.</p></div><div class="flex justify-end gap-3"><a href="<?= e($baseUrl) ?>/compras" class="rounded-lg border border-slate-300 px-4 py-3 text-sm font-semibold">Cancelar</a><button class="rounded-lg bg-emerald-700 px-5 py-3 text-sm font-semibold text-white">Guardar compra e ingresar stock</button></div></form>
<dialog id="product-modal" class="w-[min(92vw,48rem)] rounded-xl p-0 shadow-2xl backdrop:bg-slate-900/50"><div class="border-b border-slate-200 p-4"><div class="flex items-center justify-between"><h2 id="product-modal-title" class="text-lg font-bold">Seleccionar producto</h2><button type="button" class="close-product-modal rounded px-3 py-1 text-slate-600" aria-label="Cerrar">✕</button></div><input id="product-search" type="search" placeholder="Buscar por código o nombre…" class="mt-3 min-h-11 w-full rounded-lg border border-slate-300 px-3 text-sm"></div><div class="max-h-[60vh] overflow-y-auto p-3"><div id="product-options" class="divide-y divide-slate-100"><?php foreach ($products as $product): ?><button type="button" class="choose-product flex w-full items-center justify-between gap-3 rounded-lg p-3 text-left hover:bg-emerald-50" data-id="<?= e($product['id']) ?>" data-label="<?= e($product['codigo'].' · '.$product['nombre'].' ('.$product['unidad_medida'].')') ?>" data-stock="<?= e($product['stock_actual']) ?>" data-search="<?= e(mb_strtolower($product['codigo'].' '.$product['nombre'])) ?>"><span><strong class="block text-sm"><?= e($product['nombre']) ?></strong><span class="text-xs text-slate-500"><?= e($product['codigo'].' · '.$product['unidad_medida']) ?></span></span><span class="text-right text-sm"><strong class="block text-emerald-800">Seleccionar</strong><span class="text-xs text-slate-500">Stock: <?= e(number_format((float)$product['stock_actual'], 3)) ?></span></span></button><?php endforeach; ?></div><p id="no-products" class="hidden p-6 text-center text-sm text-slate-500">No se encontraron productos.</p></div></dialog>
<script>
(() => {
 const container = document.getElementById('purchase-lines');
 const modal = document.getElementById('product-modal'); let activeRow = null;
 const reindex = () => [...container.querySelectorAll('.purchase-line')].forEach((row, i) => row.querySelectorAll('[name]').forEach(el => el.name = el.name.replace(/items\[\d+\]/, `items[${i}]`)));
 document.getElementById('add-row').addEventListener('click', () => { const row = container.querySelector('.purchase-line').cloneNode(true); row.querySelectorAll('input').forEach(input => input.value = ''); row.querySelector('.open-product-modal').textContent = 'Seleccionar producto…'; container.appendChild(row); reindex(); });
 container.addEventListener('click', event => { if (event.target.closest('.open-product-modal')) { activeRow = event.target.closest('.purchase-line'); modal.showModal(); document.getElementById('product-search').value=''; filterProducts(''); document.getElementById('product-search').focus(); } });
 document.getElementById('product-options').addEventListener('click', event => { const choice=event.target.closest('.choose-product'); if(!choice||!activeRow)return; activeRow.querySelector('.product-id').value=choice.dataset.id; activeRow.querySelector('.open-product-modal').textContent=choice.dataset.label; activeRow.querySelector('.product-stock').textContent='Stock actual: '+Number(choice.dataset.stock).toFixed(3)+' unidades'; modal.close(); });
 document.getElementById('product-search').addEventListener('input', event=>filterProducts(event.target.value));
 function filterProducts(query){let shown=0;document.querySelectorAll('.choose-product').forEach(button=>{const match=button.dataset.search.includes(query.trim().toLowerCase());button.hidden=!match;if(match)shown++;});document.getElementById('no-products').classList.toggle('hidden',shown>0);}
 document.querySelectorAll('.close-product-modal').forEach(button=>button.addEventListener('click',()=>modal.close()));
 container.addEventListener('click', event => { if (event.target.classList.contains('remove-row') && container.querySelectorAll('.purchase-line').length > 1) { event.target.closest('.purchase-line').remove(); reindex(); } });
})();
</script><?php endif; ?></section>
